func main() {
	args := os.Args
	prog := filepath.Base(args[0])

	if len(args) < 2 {
		printHelp(prog, false)
		os.Exit(2)
	}

	// Parse global options and find the command
	globalOpts := GlobalOpts{OutputFormat: "human"}
	cmdStart := 1

	for i := 1; i < len(args); i++ {
		arg := args[i]
		if arg == "-h" {
			printHelp(prog, false)
			os.Exit(0)
		} else if arg == "--help" {
			printHelp(prog, true)
			os.Exit(0)
		} else if arg == "-V" || arg == "--version" {
			fmt.Printf("oranda %s\n", VERSION)
			os.Exit(0)
		} else if arg == "-v" || arg == "--verbose" {
			globalOpts.Verbose = true
		} else if arg == "--output-format" {
			if i+1 >= len(args) {
				fmt.Fprintf(os.Stderr, "error: '--output-format' requires an argument\n\nUsage: %s [OPTIONS] <COMMAND>\n\nFor more information, try '--help'.\n", prog)
				os.Exit(2)
			}
			i++
			globalOpts.OutputFormat = args[i]
			if globalOpts.OutputFormat != "human" && globalOpts.OutputFormat != "json" {
				fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--output-format <OUTPUT_FORMAT>'\n  [possible values: human, json]\n\nFor more information, try '--help'.\n", globalOpts.OutputFormat)
				os.Exit(2)
			}
		} else if strings.HasPrefix(arg, "--output-format=") {
			globalOpts.OutputFormat = strings.TrimPrefix(arg, "--output-format=")
			if globalOpts.OutputFormat != "human" && globalOpts.OutputFormat != "json" {
				fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--output-format <OUTPUT_FORMAT>'\n  [possible values: human, json]\n\nFor more information, try '--help'.\n", globalOpts.OutputFormat)
				os.Exit(2)
			}
		} else if !strings.HasPrefix(arg, "-") || arg == "--" {
			cmdStart = i
			break
		} else {
			// Unknown flag
			fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\nUsage: %s [OPTIONS] <COMMAND>\n\nFor more information, try '--help'.\n", arg, prog)
			os.Exit(2)
		}
	}

	if cmdStart >= len(args) {
		printHelp(prog, false)
		os.Exit(2)
	}

	cmd := args[cmdStart]
	cmdArgs := args[cmdStart+1:]

	switch cmd {
	case "build":
		runBuild(prog, globalOpts, cmdArgs)
	case "dev":
		runDev(prog, globalOpts, cmdArgs)
	case "serve":
		runServe(prog, globalOpts, cmdArgs)
	case "generate":
		runGenerate(prog, globalOpts, cmdArgs)
	case "help":
		if len(cmdArgs) == 0 {
			printHelp(prog, false)
			os.Exit(0)
		}
		// help <subcommand>
		switch cmdArgs[0] {
		case "build":
			printBuildHelp(prog, true)
			os.Exit(0)
		case "dev":
			printDevHelp(prog, true)
			os.Exit(0)
		case "serve":
			printServeHelp(prog, true)
			os.Exit(0)
		case "generate":
			printGenerateHelp(prog, true)
			os.Exit(0)
		default:
			printHelp(prog, false)
			os.Exit(0)
		}
	default:
		// Check for similar command suggestion
		similar := findSimilarCommand(cmd)
		if similar != "" {
			fmt.Fprintf(os.Stderr, "error: unrecognized subcommand '%s'\n\n  tip: a similar subcommand exists: '%s'\n\nUsage: %s [OPTIONS] <COMMAND>\n\nFor more information, try '--help'.\n", cmd, similar, prog)
		} else {
			fmt.Fprintf(os.Stderr, "error: unrecognized subcommand '%s'\n\nUsage: %s [OPTIONS] <COMMAND>\n\nFor more information, try '--help'.\n", cmd, prog)
		}
		os.Exit(2)
	}
}

func findSimilarCommand(cmd string) string {
	commands := []string{"build", "dev", "serve", "generate", "help"}
	// Simple similarity: prefix match or edit distance 1-2
	for _, c := range commands {
		if strings.HasPrefix(c, cmd) || strings.HasPrefix(cmd, c) {
			return c
		}
	}
	// Check edit distance
	for _, c := range commands {
		if editDistance(cmd, c) <= 2 {
			return c
		}
	}
	return ""
}

func editDistance(a, b string) int {
	if len(a) == 0 {
		return len(b)
	}
	if len(b) == 0 {
		return len(a)
	}
	if a[0] == b[0] {
		return editDistance(a[1:], b[1:])
	}
	d1 := editDistance(a[1:], b) + 1
	d2 := editDistance(a, b[1:]) + 1
	d3 := editDistance(a[1:], b[1:]) + 1
	if d1 < d2 && d1 < d3 {
		return d1
	}
	if d2 < d3 {
		return d2
	}
	return d3
}

