}

func runBuild(prog string, globalOpts GlobalOpts, args []string) {
	jsonOnly := false

	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch arg {
		case "--json-only":
			jsonOnly = true
		case "-h":
			printBuildHelp(prog, false)
			os.Exit(0)
		case "--help":
			printBuildHelp(prog, true)
			os.Exit(0)
		case "-v", "--verbose":
			globalOpts.Verbose = true
		case "--output-format":
			if i+1 < len(args) {
				i++
				globalOpts.OutputFormat = args[i]
			}
		default:
			if strings.HasPrefix(arg, "--output-format=") {
				globalOpts.OutputFormat = strings.TrimPrefix(arg, "--output-format=")
			} else {
				fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\nUsage: %s build [OPTIONS]\n\nFor more information, try '--help'.\n", arg, prog)
				os.Exit(2)
			}
		}
	}

	// Load config
	config, configPath, err := loadConfig()
	if err != nil {
		if parseErr, ok := err.(*ConfigParseError); ok {
			printConfigError(globalOpts.OutputFormat, configPath, parseErr.Message, parseErr.Cause, parseErr.Offset, parseErr.Length)
		} else if repoErr, ok := err.(*RepoError); ok {
			printRepoError(globalOpts.OutputFormat, repoErr)
		} else {
			printError(globalOpts.OutputFormat, "failed to load config", []string{err.Error()})
		}
		os.Exit(255)
	}

	// Check for Cargo.toml auto-detection
	tryAutoDetect(globalOpts)

	// Validate repository (warning only)
	if config.Project != nil && config.Project.Repository != nil {
		repo := *config.Project.Repository
		if repoErr := validateRepository(repo); repoErr != nil {
			if re, ok := repoErr.(*RepoError); ok {
				fmt.Fprintf(os.Stderr, "  × %s\n", re.Message)
				fmt.Fprintf(os.Stderr, "  help: %s\n\n", re.Help)
			}
		}
	}

	distDir := getDistDir(config)

	if jsonOnly {
		// Create dist dir and exit
		if err := os.MkdirAll(distDir, 0755); err != nil {
			printError(globalOpts.OutputFormat, "failed to create output directory", []string{err.Error()})
			os.Exit(255)
		}
		// Check if we need to fetch anything from GitHub
		if needsGitHubFetch(config) {
			// This will block trying to connect to GitHub
			fetchGitHubData(config)
		}
		printSuccess(fmt.Sprintf("Your site build is located in `%s`.", distDir))
		os.Exit(0)
	}

	// Full build - requires network for CSS
	if err := os.MkdirAll(distDir, 0755); err != nil {
		printError(globalOpts.OutputFormat, "failed to create output directory", []string{err.Error()})
		os.Exit(255)
	}

	// Write favicon
	writeFavicon(distDir)

	// Fetch CSS from CDN (will block if no network)
	fetchCSS(config, distDir)

	printSuccess(fmt.Sprintf("Your site build is located in `%s`.", distDir))
}

func printRepoError(outputFormat string, re *RepoError) {
	if outputFormat == "json" {
		diag := map[string]interface{}{
			"diagnostic": map[string]interface{}{
				"message":  re.Message,
				"severity": "error",
				"causes":   []string{},
				"filename": nil,
				"labels":   []interface{}{},
				"related":  []interface{}{},
			},
		}
		b, _ := json.Marshal(diag)
		fmt.Println(string(b))
	}
	fmt.Fprintf(os.Stderr, "  × %s\n", re.Message)
	if re.Help != "" {
		fmt.Fprintf(os.Stderr, "  help: %s\n", re.Help)
	}
	fmt.Fprintf(os.Stderr, "\n")
}

func needsGitHubFetch(config *OrandaConfig) bool {
	if config.Project == nil || config.Project.Repository == nil {
		return false
	}
	repo := *config.Project.Repository
	return strings.Contains(repo, "github.com")
