}

func wrapText(s string, maxWidth int) string {
	if len(s) <= maxWidth {
		return s
	}
	// Simple word wrap
	words := strings.Fields(s)
	var lines []string
	var currentLine strings.Builder
	indent := "      " // for continuation lines after ╰─▶

	for _, word := range words {
		if currentLine.Len() == 0 {
			currentLine.WriteString(word)
		} else if currentLine.Len()+1+len(word) <= maxWidth {
			currentLine.WriteByte(' ')
			currentLine.WriteString(word)
		} else {
			lines = append(lines, currentLine.String())
			currentLine.Reset()
			currentLine.WriteString(word)
		}
	}
	if currentLine.Len() > 0 {
		lines = append(lines, currentLine.String())
	}
	return strings.Join(lines, "\n"+indent)
}

func printSourceSnippet(w io.Writer, filename string, content []byte, offset, length int) {
	// Find line and column from offset
	line := 1
	col := 1
	for i, b := range content {
		if i == offset {
			break
		}
		if b == '\n' {
			line++
			col = 1
		} else {
			col++
		}
	}

	// Get context lines (show line before, target line, line after)
	lines := strings.Split(string(content), "\n")

	lineNumWidth := len(strconv.Itoa(len(lines)))
	if lineNumWidth < 1 {
		lineNumWidth = 1
	}

	fmt.Fprintf(w, "   ╭─[%s:%d:%d]\n", filename, 1, 1)

	// Show lines around the error
	startLine := line - 1
	endLine := line + 1
	if startLine < 1 {
		startLine = 1
	}
	if endLine > len(lines) {
		endLine = len(lines)
	}

	for i := startLine; i <= endLine; i++ {
		lineContent := ""
		if i <= len(lines) {
			lineContent = lines[i-1]
		}
		lineNum := fmt.Sprintf("%*d", lineNumWidth, i)
		fmt.Fprintf(w, " %s │ %s\n", lineNum, lineContent)

		// If this is the error line, add the pointer
		if i == line {
			// Calculate column position in the displayed line
			// col is 1-indexed
			colIdx := col - 1
			if colIdx < 0 {
				colIdx = 0
			}
			// Count actual character width (handling Unicode)
			displayedStr := lineContent
			if colIdx <= len(displayedStr) {
				prefix := displayedStr[:colIdx]
				prefixWidth := utf8.RuneCountInString(prefix)
				pointerLine := strings.Repeat(" ", lineNumWidth+3+prefixWidth) + "─"
				fmt.Fprintf(w, "   · %s\n", pointerLine[4:])
			}
		}
	}
	fmt.Fprintf(w, "   ╰────\n")
}

// loadConfig loads the oranda.json config
func loadConfig() (*OrandaConfig, string, error) {
	configPath := "./oranda.json"
	data, err := os.ReadFile(configPath)
	if err != nil {
		if os.IsNotExist(err) {
			return &OrandaConfig{}, configPath, nil
		}
		return nil, configPath, fmt.Errorf("failed to read config: %w", err)
	}

	// Try to parse as array first (for better error messages matching original)
	// Actually the original serde parser would fail differently
	// Let's parse as the full config
	config, parseErr := parseConfig(data)
	if parseErr != nil {
		return nil, configPath, parseErr
	}
	return config, configPath, nil
}

type ConfigParseError struct {
	Message string
	Cause   string
	Offset  int
	Length  int
}

func (e *ConfigParseError) Error() string {
	return e.Message + ": " + e.Cause
}

func parseConfig(data []byte) (*OrandaConfig, error) {
	// Use a strict JSON decoder to catch unknown fields
	var config OrandaConfig

	// Unmarshal strictly
	dec := json.NewDecoder(strings.NewReader(string(data)))
	dec.DisallowUnknownFields()

	if err := dec.Decode(&config); err != nil {
		// Parse the error to get offset
		offset := -1
		length := 1
		cause := err.Error()

		// Try to parse offset from error
		if jerr, ok := err.(*json.SyntaxError); ok {
			offset = int(jerr.Offset) - 1
		} else if jerr, ok := err.(*json.UnmarshalTypeError); ok {
			offset = int(jerr.Offset) - 1
		}

		// For unknown field errors, try to find the field
		if strings.Contains(cause, "unknown field") {
			// Extract field name
			if start := strings.Index(cause, `"`); start >= 0 {
				if end := strings.Index(cause[start+1:], `"`); end >= 0 {
					// fieldName := cause[start+1 : start+1+end]
					// Try to find offset in data
					// This is a best-effort approach
					offset = findFieldOffset(data, cause)
				}
			}
		}

		// Parse line/col from serde error message
		if lineCol := parseLineCol(cause); lineCol != nil {
			offset = lineColToOffset(data, lineCol[0], lineCol[1])
			length = 1
		}

		return nil, &ConfigParseError{
			Message: "failed to parse JSON",
			Cause:   cause,
			Offset:  offset,
			Length:  length,
		}
	}

	// Validate specific fields
	if config.Project != nil && config.Project.Repository != nil {
		repo := *config.Project.Repository
		if err := validateRepository(repo); err != nil {
			return nil, err
		}
	}

	return &config, nil
}

type RepoError struct {
	Message string
	Help    string
}

func (e *RepoError) Error() string {
	return e.Message
}

func validateRepository(repo string) error {
	// Must be a valid URL
	if !strings.HasPrefix(repo, "http://") && !strings.HasPrefix(repo, "https://") && !strings.HasPrefix(repo, "git@") {
		return &RepoError{
			Message: fmt.Sprintf("Your repository URL %s couldn't be parsed.", repo),
			Help:    "only git-compatible URLs are supported.",
		}
	}
	// Must be GitHub
	if strings.Contains(repo, "github.com") {
		return nil
	}
	return &RepoError{
		Message: fmt.Sprintf("Your repository URL %s couldn't be parsed.", repo),
		Help:    "Only GitHub URLs are supported at the moment.",
	}
}

func findFieldOffset(data []byte, errMsg string) int {
	// Extract field name from error message
	var fieldName string
	if start := strings.Index(errMsg, `"`); start >= 0 {
		if end := strings.Index(errMsg[start+1:], `"`); end >= 0 {
			fieldName = errMsg[start+1 : start+1+end]
		}
	}

	if fieldName == "" {
		return -1
	}

	// Find the field in the data
	target := `"` + fieldName + `"`
	idx := strings.Index(string(data), target)
	if idx >= 0 {
		// Point to after the field name (before the colon)
		return idx + len(target) - 1 + 1 // point to closing quote + 1
	}
	return -1
}

type lineColPair [2]int

func parseLineCol(errMsg string) *lineColPair {
	// Look for "at line N column M" pattern
	lineIdx := strings.Index(errMsg, "at line ")
	if lineIdx < 0 {
		return nil
	}
	rest := errMsg[lineIdx+8:]
	colIdx := strings.Index(rest, " column ")
	if colIdx < 0 {
		return nil
	}
	lineStr := rest[:colIdx]
	rest2 := rest[colIdx+8:]

	// Get column number (may have trailing text)
	colStr := rest2
	for i, c := range rest2 {
		if c < '0' || c > '9' {
			colStr = rest2[:i]
			break
		}
	}

	line, err1 := strconv.Atoi(lineStr)
	col, err2 := strconv.Atoi(colStr)
	if err1 != nil || err2 != nil {
		return nil
	}

	p := lineColPair{line, col}
	return &p
}

func lineColToOffset(data []byte, line, col int) int {
	currentLine := 1
	for i, b := range data {
		if currentLine == line {
			// col is 1-indexed position in line
			lineStart := i - (col - 1)
			_ = lineStart
			return i - 1 + col - 1
		}
		if b == '\n' {
			currentLine++
		}
	}
	return len(data) - 1
}

// getDistDir returns the dist directory from config
func getDistDir(config *OrandaConfig) string {
	if config.Build != nil && config.Build.DistDir != nil {
		return *config.Build.DistDir
	}
	return DEFAULT_DIST_DIR
}

func printBuildHelp(prog string, long bool) {
	if long {
		fmt.Printf("Build an oranda site\n\n")
		fmt.Printf("Usage: %s build [OPTIONS]\n\n", prog)
		fmt.Printf("Options:\n")
		fmt.Printf("      --json-only\n")
		fmt.Printf("          Only build the artifacts JSON file (if applicable) and other files that may be used to\n")
		fmt.Printf("          support it, such as installer source files\n\n")
		fmt.Printf("  -h, --help\n")
		fmt.Printf("          Print help (see a summary with '-h')\n\n")
		printGlobalOptions(true)
	} else {
		fmt.Printf("Build an oranda site\n\n")
		fmt.Printf("Usage: %s build [OPTIONS]\n\n", prog)
		fmt.Printf("Options:\n")
		fmt.Printf("      --json-only  Only build the artifacts JSON file (if applicable) and other files that may be\n")
		fmt.Printf("                   used to support it, such as installer source files\n")
		fmt.Printf("  -h, --help       Print help (see more with '--help')\n\n")
		printGlobalOptions(false)
	}
}

func runBuild(prog string, globalOpts GlobalOpts, args []string) {
	jsonOnly := false

	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch arg {
		case "--json-only":
			jsonOnly = true
		case "-h":
			printBuildHelp(prog, false)
			os.Exit(0)
		case "--help":
			printBuildHelp(prog, true)
			os.Exit(0)
		case "-v", "--verbose":
			globalOpts.Verbose = true
		case "--output-format":
			if i+1 < len(args) {
				i++
				globalOpts.OutputFormat = args[i]
			}
		default:
			if strings.HasPrefix(arg, "--output-format=") {
				globalOpts.OutputFormat = strings.TrimPrefix(arg, "--output-format=")
			} else {
				fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\nUsage: %s build [OPTIONS]\n\nFor more information, try '--help'.\n", arg, prog)
				os.Exit(2)
			}
		}
	}

	// Load config
	config, configPath, err := loadConfig()
	if err != nil {
		if parseErr, ok := err.(*ConfigParseError); ok {
			printConfigError(globalOpts.OutputFormat, configPath, parseErr.Message, parseErr.Cause, parseErr.Offset, parseErr.Length)
		} else if repoErr, ok := err.(*RepoError); ok {
			printRepoError(globalOpts.OutputFormat, repoErr)
		} else {
			printError(globalOpts.OutputFormat, "failed to load config", []string{err.Error()})
		}
		os.Exit(255)
	}

	// Check for Cargo.toml auto-detection
	tryAutoDetect(globalOpts)

	// Validate repository (warning only)
	if config.Project != nil && config.Project.Repository != nil {
		repo := *config.Project.Repository
		if repoErr := validateRepository(repo); repoErr != nil {
			if re, ok := repoErr.(*RepoError); ok {
				fmt.Fprintf(os.Stderr, "  × %s\n", re.Message)
				fmt.Fprintf(os.Stderr, "  help: %s\n\n", re.Help)
			}
		}
	}

	distDir := getDistDir(config)

	if jsonOnly {
		// Create dist dir and exit
		if err := os.MkdirAll(distDir, 0755); err != nil {
			printError(globalOpts.OutputFormat, "failed to create output directory", []string{err.Error()})
			os.Exit(255)
		}
		// Check if we need to fetch anything from GitHub
		if needsGitHubFetch(config) {
			// This will block trying to connect to GitHub
			fetchGitHubData(config)
		}
		printSuccess(fmt.Sprintf("Your site build is located in `%s`.", distDir))
		os.Exit(0)
	}

	// Full build - requires network for CSS
	if err := os.MkdirAll(distDir, 0755); err != nil {
		printError(globalOpts.OutputFormat, "failed to create output directory", []string{err.Error()})
		os.Exit(255)
	}

	// Write favicon
	writeFavicon(distDir)

	// Fetch CSS from CDN (will block if no network)
	fetchCSS(config, distDir)

	printSuccess(fmt.Sprintf("Your site build is located in `%s`.", distDir))
}

func printRepoError(outputFormat string, re *RepoError) {
	if outputFormat == "json" {
		diag := map[string]interface{}{
			"diagnostic": map[string]interface{}{
				"message":  re.Message,
				"severity": "error",
				"causes":   []string{},
				"filename": nil,
				"labels":   []interface{}{},
				"related":  []interface{}{},
			},
		}
		b, _ := json.Marshal(diag)
		fmt.Println(string(b))
	}
	fmt.Fprintf(os.Stderr, "  × %s\n", re.Message)
	if re.Help != "" {
		fmt.Fprintf(os.Stderr, "  help: %s\n", re.Help)
	}
	fmt.Fprintf(os.Stderr, "\n")
}

func needsGitHubFetch(config *OrandaConfig) bool {
	if config.Project == nil || config.Project.Repository == nil {
		return false
	}
	repo := *config.Project.Repository
	return strings.Contains(repo, "github.com")
}

func tryAutoDetect(globalOpts GlobalOpts) {
	// Check for Cargo.toml
	data, err := os.ReadFile("./Cargo.toml")
	if err != nil {
		return // No Cargo.toml
	}

	// Validate with cargo metadata
	_ = data
	// We found a Cargo.toml - try to run cargo metadata
	cwd, _ := os.Getwd()
	cargoMetaErr := runCargoMetadata(cwd)
	if cargoMetaErr != "" {
		fmt.Fprintf(os.Stderr, "  ⚠ We found a potential rust project at %s/Cargo.toml but there was an issue\n", cwd)
		fmt.Fprintf(os.Stderr, "  ├─▶   × `cargo metadata` execution failed\n")
		fmt.Fprintf(os.Stderr, "  │   \n")
		fmt.Fprintf(os.Stderr, "  ╰─▶ `cargo metadata` exited with an error: %s\n", cargoMetaErr)
		fmt.Fprintf(os.Stderr, "\n")
	}
}

func runCargoMetadata(dir string) string {
	// This should run "cargo metadata --no-deps --format-version 1"
	// and return any error
	// We'll use os/exec if available
	return runCargo(dir)
}

func fetchGitHubData(config *OrandaConfig) {
	// Try to connect to GitHub API - this will block if no network
	repo := *config.Project.Repository
	// Extract owner/repo from GitHub URL
	parts := strings.Split(strings.TrimSuffix(strings.TrimPrefix(strings.TrimPrefix(repo, "https://"), "http://"), "/"), "/")
	if len(parts) >= 3 {
		owner := parts[1]
		repoName := strings.TrimSuffix(parts[2], ".git")
		url := fmt.Sprintf("https://api.github.com/repos/%s/%s/releases", owner, repoName)

		client := &http.Client{}
		req, err := http.NewRequest("GET", url, nil)
		if err != nil {
			return
		}
		req.Header.Set("User-Agent", "oranda/"+VERSION)
		resp, err := client.Do(req)
		if err != nil {
			return
		}
		defer resp.Body.Close()
	}
}

func fetchCSS(config *OrandaConfig, distDir string) {
	// Determine CSS version
	cssVersion := "0.5.0" // default
	if config.Styles != nil && config.Styles.OrandaCSSVersion != nil {
		cssVersion = *config.Styles.OrandaCSSVersion
	}

	url := fmt.Sprintf("https://github.com/axodotdev/oranda-css/releases/download/v%s/oranda.css", cssVersion)

	client := &http.Client{}
	req, err := http.NewRequest("GET", url, nil)
	if err != nil {
		return
	}
	req.Header.Set("User-Agent", "oranda/"+VERSION)

	resp, err := client.Do(req)
	if err != nil {
		return
	}
	defer resp.Body.Close()

	if resp.StatusCode == 200 {
		// Save CSS file
		cssPath := filepath.Join(distDir, "oranda.css")
		cssFile, err := os.Create(cssPath)
		if err != nil {
			return
		}
		defer cssFile.Close()
		io.Copy(cssFile, resp.Body)
	}
}

// writeFavicon writes the embedded favicon to the dist dir
func writeFavicon(distDir string) {
	faviconData := getFaviconData()
	faviconPath := filepath.Join(distDir, "favicon.ico")
	os.WriteFile(faviconPath, faviconData, 0644)
}

