func runServe(prog string, globalOpts GlobalOpts, args []string) {
	port := DEFAULT_PORT

	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch arg {
		case "--port":
			if i+1 < len(args) {
				i++
				p, err := parsePort(args[i])
				if err != nil {
					fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--port <PORT>'\n\nFor more information, try '--help'.\n", args[i])
					os.Exit(2)
				}
				port = p
			}
		case "-h":
			printServeHelp(prog, false)
			os.Exit(0)
		case "--help":
			printServeHelp(prog, true)
			os.Exit(0)
		case "-v", "--verbose":
			globalOpts.Verbose = true
		case "--output-format":
			if i+1 < len(args) {
				i++
				globalOpts.OutputFormat = args[i]
			}
		default:
			if strings.HasPrefix(arg, "--port=") {
				p, err := parsePort(strings.TrimPrefix(arg, "--port="))
				if err != nil {
					fmt.Fprintf(os.Stderr, "error: invalid value for '--port <PORT>'\n\nFor more information, try '--help'.\n")
					os.Exit(2)
				}
				port = p
			} else if strings.HasPrefix(arg, "--output-format=") {
				globalOpts.OutputFormat = strings.TrimPrefix(arg, "--output-format=")
			} else {
				fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\nUsage: %s serve [OPTIONS]\n\nFor more information, try '--help'.\n", arg, prog)
				os.Exit(2)
			}
		}
	}

	// Load config to get dist dir
	config, _, _ := loadConfig()
	distDir := DEFAULT_DIST_DIR
	if config != nil {
		distDir = getDistDir(config)
	}

	// Check if dist dir exists
	if _, err := os.Stat(distDir); os.IsNotExist(err) {
		fmt.Fprintf(os.Stderr, "  × Could not find a build in %s\n", distDir)
		fmt.Fprintf(os.Stderr, "  help: Did you remember to run `oranda build`?\n\n")
		os.Exit(255)
	}

	serveFiles(distDir, port, true)
}

func parsePort(s string) (int, error) {
	var p int
	_, err := fmt.Sscanf(s, "%d", &p)
	if err != nil || p < 1 || p > 65535 {
		return 0, fmt.Errorf("invalid port")
	}
	return p, nil
}

func serveFiles(distDir string, port int, trailingSlash bool) {
	addr := fmt.Sprintf("127.0.0.1:%d", port)

	fs := http.FileServer(http.Dir(distDir))

	mux := http.NewServeMux()
	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		// Check if path exists
		fullPath := filepath.Join(distDir, filepath.Clean(r.URL.Path))

		info, err := os.Stat(fullPath)
		if err != nil {
			w.WriteHeader(http.StatusNotFound)
			return
		}

		// If it's a directory without trailing slash, redirect
		if info.IsDir() && !strings.HasSuffix(r.URL.Path, "/") {
			http.Redirect(w, r, r.URL.Path+"/", http.StatusTemporaryRedirect)
			return
		}

		// Check for index.html in directory
		if info.IsDir() {
			indexPath := filepath.Join(fullPath, "index.html")
			if _, err := os.Stat(indexPath); os.IsNotExist(err) {
				w.WriteHeader(http.StatusNotFound)
				return
			}
		}

		fs.ServeHTTP(w, r)
	})

	ln, err := net.Listen("tcp", addr)
	if err != nil {
		fmt.Fprintf(os.Stderr, "  × Failed to bind to port %d: %v\n\n", port, err)
		os.Exit(255)
	}

	if trailingSlash {
		printSuccess(fmt.Sprintf("Your project is available at: http://127.0.0.1:%d/", port))
	} else {
		printSuccess(fmt.Sprintf("Your project is available at: http://127.0.0.1:%d", port))
	}

	server := &http.Server{Handler: mux}
	server.Serve(ln)
}
