	}

	// Watch README.md if it exists
	if _, err := os.Stat("./README.md"); err == nil {
		watchPaths = append(watchPaths, "./README.md")
	}

	// Watch CHANGELOG.md if it exists
	if _, err := os.Stat("./CHANGELOG.md"); err == nil {
		watchPaths = append(watchPaths, "./CHANGELOG.md")
	}

	// Watch additional pages if configured
	if config != nil && config.Build != nil {
		for _, pagePath := range config.Build.AdditionalPages {
			if _, err := os.Stat(pagePath); err == nil {
				watchPaths = append(watchPaths, pagePath)
			}
		}
	}

	// Add user-specified include paths (only if they exist)
	for _, p := range includePaths {
		if _, err := os.Stat(p); err == nil {
			watchPaths = append(watchPaths, p)
		}
	}

	printInfo(fmt.Sprintf("Found %d paths to watch, starting watch...", len(watchPaths)))

	// Check if dist dir exists for serving
	if _, err := os.Stat(distDir); os.IsNotExist(err) {
		// Start watch in background, serve will panic
		go watchFiles(watchPaths, globalOpts, port)

		// Print success message
		printSuccess(fmt.Sprintf("Your project is available at: http://127.0.0.1:%d", port))

		// Serve will fail since distDir doesn't exist
		// Replicate the panic behavior
		time.Sleep(100 * time.Millisecond)
		fmt.Fprintf(os.Stderr, "  × oranda panicked.\n")
		fmt.Fprintf(os.Stderr, "  ├─▶ at src/commands/dev.rs:131:62\n")
		fmt.Fprintf(os.Stderr, fmt.Sprintf("  ╰─▶ called `Result::unwrap()` on an `Err` value: BuildNotFound { dist_dir: %q }\n", distDir))
		fmt.Fprintf(os.Stderr, "  help: set the `RUST_BACKTRACE=1` environment variable to display a backtrace.\n\n")

		// Keep running for a bit to allow output to flush
		select {}
	}

	// Start serving in background
	go func() {
		// Serve files (no trailing slash for dev)
		serveFiles(distDir, port, false)
	}()

	printSuccess(fmt.Sprintf("Your project is available at: http://127.0.0.1:%d", port))

	// Watch for changes
	watchFiles(watchPaths, globalOpts, port)
}

func watchFiles(paths []string, globalOpts GlobalOpts, port int) {
	// Simple file watching using polling
	type fileState struct {
		ModTime time.Time
		Size    int64
	}

	states := make(map[string]fileState)

	// Initialize states
	for _, p := range paths {
		absPath, _ := filepath.Abs(p)
		info, err := os.Stat(absPath)
		if err == nil {
			states[absPath] = fileState{info.ModTime(), info.Size()}
		}
	}

	for {
		time.Sleep(300 * time.Millisecond)

		changed := false
		for _, p := range paths {
			absPath, _ := filepath.Abs(p)
			info, err := os.Stat(absPath)
			if err != nil {
				continue
			}

			state, exists := states[absPath]
			if !exists || info.ModTime().After(state.ModTime) || info.Size() != state.Size {
				states[absPath] = fileState{info.ModTime(), info.Size()}
				changed = true
			}
		}

		if changed {
			// Rebuild
			printInfo("File changed, rebuilding...")
			runBuildForDev(globalOpts)
		}
	}
}
