		fmt.Printf("Usage: %s generate ci [OPTIONS]\n\n", prog)
		fmt.Printf("Options:\n")
		fmt.Printf("      --ci <CI>                    What CI to generate a file for [default: github] [possible\n")
		fmt.Printf("                                   values: github]\n")
		fmt.Printf("  -o, --output-path <OUTPUT_PATH>  Path to the output file\n")
		fmt.Printf("  -s, --site-path <SITE_PATH>      Path to your oranda site\n")
		fmt.Printf("  -h, --help                       Print help (see more with '--help')\n\n")
		printGlobalOptions(false)
	}
}

func runGenerate(prog string, globalOpts GlobalOpts, args []string) {
	if len(args) == 0 {
		printGenerateHelp(prog, false)
		os.Exit(2)
	}

	// Parse generate-level options
	outputPath := ""
	sitePath := ""
	cmdStart := 0

	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch arg {
		case "-o", "--output-path":
			if i+1 < len(args) {
				i++
				outputPath = args[i]
			}
		case "-s", "--site-path":
			if i+1 < len(args) {
				i++
				sitePath = args[i]
			}
		case "-h":
			printGenerateHelp(prog, false)
			os.Exit(0)
		case "--help":
			printGenerateHelp(prog, true)
			os.Exit(0)
		case "-v", "--verbose":
			globalOpts.Verbose = true
		case "--output-format":
			if i+1 < len(args) {
				i++
				globalOpts.OutputFormat = args[i]
			}
		default:
			if strings.HasPrefix(arg, "-o=") {
				outputPath = strings.TrimPrefix(arg, "-o=")
			} else if strings.HasPrefix(arg, "--output-path=") {
				outputPath = strings.TrimPrefix(arg, "--output-path=")
			} else if strings.HasPrefix(arg, "-s=") {
				sitePath = strings.TrimPrefix(arg, "-s=")
			} else if strings.HasPrefix(arg, "--site-path=") {
				sitePath = strings.TrimPrefix(arg, "--site-path=")
			} else if strings.HasPrefix(arg, "--output-format=") {
				globalOpts.OutputFormat = strings.TrimPrefix(arg, "--output-format=")
			} else if !strings.HasPrefix(arg, "-") {
				cmdStart = i
				break
			} else {
				fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\nUsage: %s generate [OPTIONS] <COMMAND>\n\nFor more information, try '--help'.\n", arg, prog)
				os.Exit(2)
			}
		}
		if !strings.HasPrefix(arg, "-") {
			cmdStart = i
			break
		}
	}

	if cmdStart >= len(args) {
		printGenerateHelp(prog, false)
		os.Exit(2)
	}

	subcmd := args[cmdStart]
	subArgs := args[cmdStart+1:]

	switch subcmd {
	case "ci":
		runGenerateCI(prog, globalOpts, outputPath, sitePath, subArgs)
	case "help":
		if len(subArgs) > 0 && subArgs[0] == "ci" {
			printGenerateCiHelp(prog, true)
		} else {
			printGenerateHelp(prog, true)
		}
		os.Exit(0)
	default:
		fmt.Fprintf(os.Stderr, "error: unrecognized subcommand '%s'\n\nUsage: %s generate [OPTIONS] <COMMAND>\n\nFor more information, try '--help'.\n", subcmd, prog)
		os.Exit(2)
	}
}

func runGenerateCI(prog string, globalOpts GlobalOpts, outputPath, sitePath string, args []string) {
	ciType := "github"

	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch arg {
		case "--ci":
			if i+1 < len(args) {
				i++
				ciType = args[i]
				if ciType != "github" {
					fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--ci <CI>'\n  [possible values: github]\n\nFor more information, try '--help'.\n", ciType)
					os.Exit(2)
				}
			}
		case "-o", "--output-path":
			if i+1 < len(args) {
				i++
				outputPath = args[i]
			}
		case "-s", "--site-path":
			if i+1 < len(args) {
				i++
				sitePath = args[i]
			}
		case "-h":
			printGenerateCiHelp(prog, false)
			os.Exit(0)
		case "--help":
			printGenerateCiHelp(prog, true)
			os.Exit(0)
		case "-v", "--verbose":
			globalOpts.Verbose = true
		case "--output-format":
			if i+1 < len(args) {
				i++
				globalOpts.OutputFormat = args[i]
			}
		default:
			if strings.HasPrefix(arg, "--ci=") {
				ciType = strings.TrimPrefix(arg, "--ci=")
				if ciType != "github" {
					fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '--ci <CI>'\n  [possible values: github]\n\nFor more information, try '--help'.\n", ciType)
					os.Exit(2)
				}
			} else if strings.HasPrefix(arg, "--output-path=") {
				outputPath = strings.TrimPrefix(arg, "--output-path=")
			} else if strings.HasPrefix(arg, "--site-path=") {
				sitePath = strings.TrimPrefix(arg, "--site-path=")
			} else if strings.HasPrefix(arg, "--output-format=") {
				globalOpts.OutputFormat = strings.TrimPrefix(arg, "--output-format=")
			} else {
				fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\nUsage: %s generate ci [OPTIONS]\n\nFor more information, try '--help'.\n", arg, prog)
				os.Exit(2)
			}
		}
	}

	printInfo("Generating a CI deploy workflow for your site...")

	// Check if it's a TTY
	if !isTTY() {
		// Panic with NotTTY error
		fmt.Fprintf(os.Stderr, "  × oranda panicked.\n")
		fmt.Fprintf(os.Stderr, "  ├─▶ at src/generate.rs:56:14\n")
		fmt.Fprintf(os.Stderr, "  ╰─▶ Error while prompting!: NotTTY\n")
		fmt.Fprintf(os.Stderr, "  help: set the `RUST_BACKTRACE=1` environment variable to display a backtrace.\n\n")
		os.Exit(255)
	}

	// Ask questions
	includeLinkChecker := promptConfirm(
		"Do you want to include a tool for checking generated hyperlinks?",
		"[Read more about the link checker tool: https://github.com/untitaker/hyperlink]",
		true,
	)

	useLatestVersion := promptConfirm(
		"Do you want to always use the latest version of oranda?",
		"[Using the latest version means you don't have to rerun this command when oranda\n updates, but it may also break your site if you use a lot of configuration!]",
		false,
	)

	addToGitignore := promptConfirm(
		"Would you like to append the default destination directory (`public`) to your .gitignore file?",
		"",
		false,
	)

	// Generate CI file
	var ciContent string
	if ciType == "github" {
		ciContent = generateGitHubCI(includeLinkChecker, useLatestVersion, sitePath)
	}

	// Write CI file
	if outputPath == "" {
		outputPath = "./.github/workflows/web.yml"
	}

	// Create directory
	dir := outputPath[:strings.LastIndex(outputPath, "/")+0]
	if lastSlash := strings.LastIndex(outputPath, "/"); lastSlash >= 0 {
		dir = outputPath[:lastSlash]
		if dir != "" {
			os.MkdirAll(dir, 0755)
		}
	}

	if err := os.WriteFile(outputPath, []byte(ciContent), 0644); err != nil {
		fmt.Fprintf(os.Stderr, "  × Failed to write CI file: %v\n\n", err)
		os.Exit(255)
	}

	// Handle .gitignore
	if addToGitignore {
		appendToGitignore()
	}

	printSuccess(fmt.Sprintf("Wrote CI file to %q", outputPath))
}

func isTTY() bool {
	// Check if stdin is a TTY
	fi, err := os.Stdin.Stat()
	if err != nil {
		return false
	}
	// Check if it's a character device (TTY)
	return (fi.Mode() & os.ModeCharDevice) != 0
}

func promptConfirm(question, hint string, defaultYes bool) bool {
	defaultStr := "y/N"
	if defaultYes {
		defaultStr = "Y/n"
	}

	fmt.Printf("? >o_o< %s (%s)\n", question, defaultStr)
	if hint != "" {
		fmt.Printf("%s\n", hint)
	}

	reader := bufio.NewReader(os.Stdin)
	answer, err := reader.ReadString('\n')
	if err != nil {
		return defaultYes
	}

	answer = strings.TrimSpace(strings.ToLower(answer))

	var result bool
	var displayAnswer string

	if answer == "" {
		result = defaultYes
		if defaultYes {
			displayAnswer = "Yes"
		} else {
			displayAnswer = "No"
		}
	} else if answer == "y" || answer == "yes" {
		result = true
		displayAnswer = "Yes"
	} else {
		result = false
		displayAnswer = "No"
	}

	// Print the confirmed answer (overwrite the question)
	fmt.Printf("> >o_o< %s %s\n", question, displayAnswer)

	return result
}

func appendToGitignore() {
	content := "\n# Generated by `oranda generate ci`\npublic/"

	// Check if .gitignore exists
	existing, err := os.ReadFile(".gitignore")
	if err == nil {
		// File exists - append
		var newContent []byte
		if len(existing) > 0 && existing[len(existing)-1] != '\n' {
			// Add a newline before our content
			newContent = append(existing, []byte("\n"+strings.TrimPrefix(content, "\n"))...)
		} else {
			newContent = append(existing, []byte(content)...)
		}
		os.WriteFile(".gitignore", newContent, 0644)
	} else {
		// File doesn't exist - create it
		os.WriteFile(".gitignore", []byte(content), 0644)
	}
}

func generateGitHubCI(includeLinkChecker, useLatestVersion bool, sitePath string) string {
	var sb strings.Builder

	// Determine installer URL
	var installerURL string
	if useLatestVersion {
		installerURL = "https://github.com/axodotdev/oranda/releases/latest/download/oranda-installer.sh"
	} else {
		installerURL = "https://github.com/axodotdev/oranda/releases/download/v0.6.1/oranda-installer.sh"
	}

	// Build run step
	var runLines strings.Builder
	runLines.WriteString(fmt.Sprintf("          curl --proto '=https' --tlsv1.2 -LsSf %s | sh\n", installerURL))
	if sitePath != "" {
		runLines.WriteString(fmt.Sprintf("          cd %s\n", sitePath))
	}
	runLines.WriteString("          oranda build")

	sb.WriteString(`# Workflow to build your docs with oranda (and mdbook)
# and deploy them to Github Pages
name: Web

# We're going to push to the gh-pages branch, so we need that permission
permissions:
  contents: write

# What situations do we want to build docs in?
# All of these work independently and can be removed / commented out
# if you don't want oranda/mdbook running in that situation
on:
  # Check that a PR didn't break docs!
  #
  # Note that the "Deploy to Github Pages" step won't run in this mode,
  # so this won't have any side-effects. But it will tell you if a PR
  # completely broke oranda/mdbook. Sadly we don't provide previews (yet)!
  pull_request:

  # Whenever something gets pushed to main, update the docs!
  # This is great for getting docs changes live without cutting a full release.
  #
  # Note that if you're using cargo-dist, this will "race" the Release workflow
  # that actually builds the Github Release that oranda tries to read (and
  # this will almost certainly complete first). As a result you will publish
  # docs for the latest commit but the oranda landing page won't know about
  # the latest release. The workflow_run trigger below will properly wait for
  # cargo-dist, and so this half-published state will only last for ~10 minutes.
  #
  # If you only want docs to update with releases, disable this, or change it to
  # a "release" branch. You can, of course, also manually trigger a workflow run
  # when you want the docs to update.
  push:
    branches:
      - main

  # Whenever a workflow called "Release" completes, update the docs!
  #
  # If you're using cargo-dist, this is recommended, as it will ensure that
  # oranda always sees the latest release right when it's available. Note
  # however that Github's UI is wonky when you use workflow_run, and won't
  # show this workflow as part of any commit. You have to go to the "actions"
  # tab for your repo to see this one running (the gh-pages deploy will also
  # only show up there).
  workflow_run:
    workflows: [ "Release" ]
    types:
      - completed

# Alright, let's do it!
jobs:
  web:
    name: Build and deploy site and docs
    runs-on: ubuntu-latest
    steps:
      # Setup
      - uses: actions/checkout@v3
        with:
          fetch-depth: 0
      - uses: dtolnay/rust-toolchain@stable
      - uses: swatinem/rust-cache@v2

      # If you use any mdbook plugins, here's the place to install them!

      # Install and run oranda (and mdbook)!
      #
      # This will write all output to ./public/ (including copying mdbook's output to there).
      - name: Install and run oranda
        run: |
`)
	sb.WriteString(runLines.String())
	sb.WriteString("\n")

	if includeLinkChecker {
		sb.WriteString(`      
      - name: Prepare HTML for link checking
        # untitaker/hyperlink supports no site prefixes, move entire site into
        # a subfolder
        run: mkdir /tmp/public/ && cp -R public /tmp/public/oranda

      - name: Check HTML for broken internal links
        uses: untitaker/hyperlink@0.1.29
        with:
          args: /tmp/public/
`)
	}

	sb.WriteString(`      
      # Deploy to our gh-pages branch (creating it if it doesn't exist).
      # The "public" dir that oranda made above will become the root dir
      # of this branch.
      #
      # Note that once the gh-pages branch exists, you must
      # go into repo's settings > pages and set "deploy from branch: gh-pages".
      # The other defaults work fine.
      - name: Deploy to Github Pages
        uses: JamesIves/github-pages-deploy-action@v4.4.1
        # ONLY if we're on main (so no PRs or feature branches allowed!)
        if: ${{ github.ref == 'refs/heads/main' }}
        with:
          branch: gh-pages
          # Gotta tell the action where to find oranda's output
          folder: public
          token: ${{ secrets.GITHUB_TOKEN }}
          single-commit: true`)

	return sb.String()
}
