// ConfigValidationError holds validation error details
type ConfigValidationError struct {
	Message string
	Cause   string
	Offset  int
	Length  int
}

func (e *ConfigValidationError) Error() string {
	return fmt.Sprintf("%s: %s", e.Message, e.Cause)
}

// findFieldByteOffset finds the byte offset of a field name in the JSON content
func findFieldByteOffset(content []byte, fieldName string, startOffset int) int {
	// Search for "fieldName" in content starting from startOffset
	needle := `"` + fieldName + `"`
	for i := startOffset; i < len(content)-len(needle); i++ {
		if string(content[i:i+len(needle)]) == needle {
			// Return the offset of the closing quote
			return i + len(needle) - 1
		}
	}
	return startOffset
}

// lineColToByteOffset converts line/col to byte offset in content
func lineColToByteOffset(content []byte, line, col int) int {
	currentLine := 1
	lineStart := 0
	for i, b := range content {
		if currentLine == line {
			// col is 1-indexed
			offset := lineStart + col - 1
			if offset < len(content) {
				return offset
			}
			return len(content) - 1
		}
		if b == '\n' {
			currentLine++
			lineStart = i + 1
		}
	}
	return len(content) - 1
}

