func missingFieldError(content []byte, filename string, field string, parentRaw json.RawMessage) *ConfigValidationError {
	// Find the closing brace of the parent
	// The error points to the closing brace
	str := string(content)
	parentStr := string(parentRaw)
	idx := strings.Index(str, parentStr)
	offset := 0
	line := 1
	col := 1
	if idx >= 0 {
		// Find closing brace
		closingIdx := idx + len(parentStr) - 1
		// Find the brace
		for i := closingIdx; i >= idx; i-- {
			if content[i] == '}' {
				offset = i
				// Calculate line/col
				for j := 0; j < i; j++ {
					if content[j] == '\n' {
						line++
						col = 1
					} else {
						col++
					}
				}
				col++ // point to the char after
				break
			}
		}
	}

	cause := fmt.Sprintf("missing field `%s` at line %d column %d", field, line, col)

	return &ConfigValidationError{
		Message: "failed to parse JSON",
		Cause:   cause,
		Offset:  offset,
		Length:  1,
	}
}

func findFieldLocation(content []byte, fieldName string) (offset, line, col int) {
	// Find the first occurrence of "fieldName" in content
	needle := `"` + fieldName + `"`
	str := string(content)
	idx := strings.Index(str, needle)
	if idx < 0 {
		return 0, 1, 1
	}

	// Point to the closing quote
	closeIdx := idx + len(needle) - 1

	// Calculate line and col for the closing quote
	line = 1
	col = 1
	for i := 0; i < closeIdx; i++ {
		if content[i] == '\n' {
			line++
			col = 1
		} else {
			col++
		}
	}
	col++ // 1-indexed position of the closing quote

	return closeIdx, line, col
}

func findValueLocation(content []byte, fieldName, value string) (offset, line, col int) {
	// Find the field, then find the value after it
	needle := `"` + fieldName + `"`
	str := string(content)
	idx := strings.Index(str, needle)
	if idx < 0 {
		return 0, 1, 1
	}

	// After the field name, find the value
	afterField := str[idx+len(needle):]
	valueNeedle := `"` + value + `"`
	valIdx := strings.Index(afterField, valueNeedle)
	if valIdx < 0 {
		return 0, 1, 1
	}

	absoluteIdx := idx + len(needle) + valIdx + len(valueNeedle) - 1

	line = 1
	col = 1
	for i := 0; i < absoluteIdx; i++ {
		if content[i] == '\n' {
			line++
			col = 1
		} else {
			col++
		}
	}
	col++

	return absoluteIdx, line, col
}

func jsonParseError(content []byte, filename string, err error) *ConfigValidationError {
	if err == nil {
		return nil
	}

	errStr := err.Error()
	offset := -1
	line := 1
	col := 1

	// Try to parse line/col from the error
	if jerr, ok := err.(*json.SyntaxError); ok {
		offset = int(jerr.Offset) - 1
		// Calculate line/col
		for i := 0; i < int(jerr.Offset) && i < len(content); i++ {
			if content[i] == '\n' {
				line++
				col = 1
			} else {
				col++
			}
		}
	} else if jerr, ok := err.(*json.UnmarshalTypeError); ok {
		offset = int(jerr.Offset) - 1
		for i := 0; i < int(jerr.Offset) && i < len(content); i++ {
			if content[i] == '\n' {
				line++
				col = 1
			} else {
				col++
			}
		}
	}

	// Convert Go JSON error to serde-compatible message
	cause := convertGoJSONError(errStr, line, col)

	if offset < 0 {
		offset = lineColToByteOffset(content, line, col)
	}

	return &ConfigValidationError{
		Message: "failed to parse JSON",
		Cause:   cause,
		Offset:  offset,
		Length:  1,
	}
}

func convertGoJSONError(errStr string, line, col int) string {
	// Convert Go JSON errors to serde_json-compatible messages
	// Remove the "json: " prefix from Go errors
	if strings.HasPrefix(errStr, "json: ") {
		errStr = errStr[6:]
	}

	// Add line/col if not present
	if !strings.Contains(errStr, " at line ") && line > 0 {
		return fmt.Sprintf("%s at line %d column %d", errStr, line, col)
	}
	return errStr
}
