const MAX_LINE_WIDTH = 119 // Lines must be < 119 chars (max 118)

// wrapCauseText wraps the cause text with proper indentation
// Returns the wrapped text (first line content, continuation lines with indent)
func wrapCauseText(cause string) []string {
	prefix := "  ╰─▶ "
	continuation := "      "
	maxWidth := MAX_LINE_WIDTH
	prefixDisplayWidth := displayWidth(prefix)  // 6
	contDisplayWidth := displayWidth(continuation) // 6
	_ = contDisplayWidth

	// Split into words (preserve backticks and their content as units)
	words := splitIntoWords(cause)

	var lines []string
	currentLine := ""
	currentWidth := prefixDisplayWidth

	for _, word := range words {
		wWidth := displayWidth(word)

		if currentLine == "" {
			// First word on this line
			currentLine = word
			currentWidth += wWidth
		} else {
			// Try to add word
			newWidth := currentWidth + 1 + wWidth // +1 for space
			if newWidth >= maxWidth {
				// Wrap
				lines = append(lines, currentLine)
				currentLine = word
				currentWidth = contDisplayWidth + wWidth
			} else {
				currentLine += " " + word
				currentWidth = newWidth
			}
		}
	}
	if currentLine != "" {
		lines = append(lines, currentLine)
	}

	return lines
}

func splitIntoWords(s string) []string {
	return strings.Fields(s)
}

func displayWidth(s string) int {
	return utf8.RuneCountInString(s)
