func runBuild(prog string, globalOpts GlobalOpts, args []string) {
	jsonOnly := false

	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch arg {
		case "--json-only":
			jsonOnly = true
		case "-h":
			printBuildHelp(prog, false)
			os.Exit(0)
		case "--help":
			printBuildHelp(prog, true)
			os.Exit(0)
		case "-v", "--verbose":
			globalOpts.Verbose = true
		case "--output-format":
			if i+1 < len(args) {
				i++
				globalOpts.OutputFormat = args[i]
			}
		default:
			if strings.HasPrefix(arg, "--output-format=") {
				globalOpts.OutputFormat = strings.TrimPrefix(arg, "--output-format=")
			} else {
				fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\nUsage: %s build [OPTIONS]\n\nFor more information, try '--help'.\n", arg, prog)
				os.Exit(2)
			}
		}
	}

	// Load config
	config, configPath, err := loadConfig()
	if err != nil {
		if valErr, ok := err.(*ConfigValidationError); ok {
			content, _ := os.ReadFile(configPath)
			printDiagnosticError(os.Stderr, globalOpts.OutputFormat, configPath, valErr.Message, valErr.Cause, valErr.Offset, valErr.Length)
			_ = content
		} else {
			printSimpleError(globalOpts.OutputFormat, "failed to load config", []string{err.Error()})
		}
		os.Exit(255)
	}

	// Check for Cargo.toml auto-detection
	tryAutoDetect()

	// Validate repository (warning only - non-fatal)
	if config.Project != nil && config.Project.Repository != nil {
		repo := *config.Project.Repository
		if repoErr := validateRepository(repo); repoErr != nil {
			if re, ok := repoErr.(*RepoError); ok {
				fmt.Fprintf(os.Stderr, "  × %s\n", re.Message)
				fmt.Fprintf(os.Stderr, "  help: %s\n\n", re.Help)
			}
		}
	}

	distDir := getDistDir(config)

	if jsonOnly {
		// Create dist dir and exit
		if err := os.MkdirAll(distDir, 0755); err != nil {
			printSimpleError(globalOpts.OutputFormat, "failed to create output directory", []string{err.Error()})
			os.Exit(255)
		}
		// Check if we need to fetch anything from GitHub (changelog/artifacts)
		if needsGitHubFetch(config) {
			fetchGitHubData(config)
		}
		printSuccess(fmt.Sprintf("Your site build is located in `%s`.", distDir))
		os.Exit(0)
	}

	// Full build
	if err := os.MkdirAll(distDir, 0755); err != nil {
		printSimpleError(globalOpts.OutputFormat, "failed to create output directory", []string{err.Error()})
		os.Exit(255)
	}

	// Write favicon
	writeFavicon(distDir)

	// Fetch CSS from CDN (will block if no network)
	fetchCSS(config, distDir)

	printSuccess(fmt.Sprintf("Your site build is located in `%s`.", distDir))
}

type RepoError struct {
	Message string
	Help    string
}

func (e *RepoError) Error() string {
	return e.Message
}

func validateRepository(repo string) error {
	if !strings.HasPrefix(repo, "http://") && !strings.HasPrefix(repo, "https://") && !strings.HasPrefix(repo, "git@") {
		return &RepoError{
			Message: fmt.Sprintf("Your repository URL %s couldn't be parsed.", repo),
			Help:    "only git-compatible URLs are supported.",
		}
	}
	if strings.Contains(repo, "github.com") {
		return nil
	}
	return &RepoError{
		Message: fmt.Sprintf("Your repository URL %s couldn't be parsed.", repo),
		Help:    "Only GitHub URLs are supported at the moment.",
	}
}

func needsGitHubFetch(config *OrandaConfig) bool {
	if config.Project == nil || config.Project.Repository == nil {
		return false
	}
	repo := *config.Project.Repository
	return strings.Contains(repo, "github.com")
}

func tryAutoDetect() {
	data, err := os.ReadFile("./Cargo.toml")
	if err != nil {
		return
	}
	_ = data

	cwd, _ := os.Getwd()
	cargoMetaErr := runCargo(cwd)
	if cargoMetaErr != "" {
		fmt.Fprintf(os.Stderr, "  ⚠ We found a potential rust project at %s/Cargo.toml but there was an issue\n", cwd)
		fmt.Fprintf(os.Stderr, "  ├─▶   × `cargo metadata` execution failed\n")
		fmt.Fprintf(os.Stderr, "  │   \n")
		fmt.Fprintf(os.Stderr, "  ╰─▶ `cargo metadata` exited with an error: %s\n", cargoMetaErr)
		fmt.Fprintf(os.Stderr, "\n")
	}
}

func fetchGitHubData(config *OrandaConfig) {
	if config.Project == nil || config.Project.Repository == nil {
		return
	}
	repo := *config.Project.Repository
	parts := strings.Split(strings.TrimPrefix(strings.TrimPrefix(repo, "https://"), "http://"), "/")
	if len(parts) >= 3 {
		owner := parts[1]
		repoName := strings.TrimSuffix(parts[2], ".git")
		url := fmt.Sprintf("https://api.github.com/repos/%s/%s/releases", owner, repoName)

		client := &http.Client{}
		req, err := http.NewRequest("GET", url, nil)
		if err != nil {
			return
		}
		req.Header.Set("User-Agent", "oranda/"+VERSION)
		resp, err := client.Do(req)
		if err != nil {
			return
		}
		defer resp.Body.Close()
	}
}

func fetchCSS(config *OrandaConfig, distDir string) {
	cssVersion := "0.5.0"
	if config.Styles != nil && config.Styles.OrandaCSSVersion != nil {
		cssVersion = *config.Styles.OrandaCSSVersion
	}

	url := fmt.Sprintf("https://github.com/axodotdev/oranda-css/releases/download/v%s/oranda.css", cssVersion)

	client := &http.Client{}
	req, err := http.NewRequest("GET", url, nil)
	if err != nil {
		return
	}
	req.Header.Set("User-Agent", "oranda/"+VERSION)

	resp, err := client.Do(req)
	if err != nil {
		return
	}
	defer resp.Body.Close()
}

func writeFavicon(distDir string) {
	faviconData := getFaviconData()
	faviconPath := filepath.Join(distDir, "favicon.ico")
	os.WriteFile(faviconPath, faviconData, 0644)
}
