func extractValueAtLocation(content []byte, line, col int) string {
	// Find the value at the given line/col position
	lines := strings.Split(string(content), "\n")
	if line > len(lines) || line < 1 {
		return "unknown"
	}

	lineStr := lines[line-1]
	if col > len(lineStr) {
		return "unknown"
	}

	// The col might point to AFTER the value; find the value
	// In serde_json, for integers it points to the last digit
	// Find the start of the value by going backwards
	startPos := col - 1
	for startPos > 0 && isValueChar(lineStr[startPos-1]) {
		startPos--
	}

	endPos := col
	for endPos < len(lineStr) && isValueChar(lineStr[endPos]) {
		endPos++
	}

	if startPos >= 0 && endPos <= len(lineStr) {
		return lineStr[startPos:endPos]
	}
	return "unknown"
}

