	// Convert to line/col
	for i := int64(0); i < offset-1 && i < int64(len(content)); i++ {
		if content[i] == '\n' {
			line++
			col = 1
		} else {
			col++
		}
	}
	col++ // point to the char at offset (1-indexed position after the loop)

	return line, col
}

