// and returns the serde-compatible message
func formatFromSyntaxErr(err *json.SyntaxError, content []byte) (string, int) {
	// Go's SyntaxError.Offset is 1-based offset of the character AFTER the error
	off := int(err.Offset) - 1
	if off < 0 {
		off = 0
	}
	if off >= len(content) {
		off = len(content) - 1
	}

	line := 1
	col := 1
	for i := 0; i < off; i++ {
		if content[i] == '\n' {
			line++
			col = 1
		} else {
			col++
		}
