		off = 0
	}

	line := 1
	col := 1
	for i := 0; i < int(err.Offset)-1 && i < len(content); i++ {
		if content[i] == '\n' {
			line++
			col = 1
		} else {
			col++
		}
	}
	col++ // 1-indexed position of the char at offset

	// Get the actual value
	var actualValue string
	switch err.Value {
	case "number":
		actualValue = extractNumberStr(content, line, col)
		typeStr := "integer"
		if strings.Contains(actualValue, ".") || strings.Contains(actualValue, "e") {
			typeStr = "float"
		}
		expectedType := "a string"
		if err.Type != nil {
			typeName := err.Type.String()
			if strings.Contains(typeName, "bool") {
				expectedType = "a boolean"
			} else if strings.Contains(typeName, "int") || strings.Contains(typeName, "float") {
				expectedType = "a number"
			} else if strings.Contains(typeName, "string") {
				expectedType = "a string"
			}
		}
		return fmt.Sprintf("invalid type: %s `%s`, expected %s at line %d column %d",
			typeStr, actualValue, expectedType, line, col), off
	case "string":
		// Extract string value
		actualValue = "unknown"
		expectedType := "the expected type"
		if err.Type != nil {
			typeName := err.Type.String()
			if strings.Contains(typeName, "bool") {
				expectedType = "a boolean"
			}
		}
		return fmt.Sprintf("invalid type: string `%s`, expected %s at line %d column %d",
			actualValue, expectedType, line, col), off
	case "bool":
		actualValue = extractBoolStr(content, line, col)
		expectedType := "a string"
		return fmt.Sprintf("invalid type: boolean `%s`, expected %s at line %d column %d",
			actualValue, expectedType, line, col), off
	case "array":
		return fmt.Sprintf("invalid type: sequence, expected a map at line %d column %d", line, col), off
	case "object":
		return fmt.Sprintf("invalid type: map, expected a string at line %d column %d", line, col), off
	default:
		return fmt.Sprintf("invalid type: %s, expected the expected type at line %d column %d",
			err.Value, line, col), off
	}
}

func extractBoolStr(content []byte, line, col int) string {
	lines := strings.Split(string(content), "\n")
	if line < 1 || line > len(lines) {
		return "unknown"
	}
	lineStr := lines[line-1]
	colIdx := col - 1
	if colIdx < 0 || colIdx >= len(lineStr) {
		return "unknown"
	}

	// Check for true/false at this position
	if strings.HasPrefix(lineStr[colIdx:], "true") {
		return "true"
	}
	if strings.HasPrefix(lineStr[colIdx:], "false") {
		return "false"
	}

	// Go backward to find start
	start := colIdx
	for start > 0 && (lineStr[start-1] == 't' || lineStr[start-1] == 'r' || lineStr[start-1] == 'u' || lineStr[start-1] == 'e' || lineStr[start-1] == 'f' || lineStr[start-1] == 'a' || lineStr[start-1] == 'l' || lineStr[start-1] == 's') {
		start--
	}
	end := colIdx + 1
	if end <= len(lineStr) {
		return lineStr[start:end]
	}
	return "unknown"
}

func convertGoSyntaxError(errStr string, line, col int) string {
	if strings.Contains(errStr, "looking for beginning of object key string") {
		return fmt.Sprintf("key must be a string at line %d column %d", line, col)
	}
	if strings.Contains(errStr, "looking for beginning of value") {
		return fmt.Sprintf("expected value at line %d column %d", line, col)
	}
	// Default
	return fmt.Sprintf("%s at line %d column %d", errStr, line, col)
}

// formatNumberValue extracts a number string at offset in content
func formatNumberValueAtOffset(content []byte, offset int) string {
	if offset < 0 || offset >= len(content) {
		return "unknown"
	}

	// Go's offset points to after the number
	end := offset
	start := end
	for start > 0 {
		c := content[start-1]
		if c >= '0' && c <= '9' || c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E' {
			start--
		} else {
			break
		}
	}

	if start < end && end <= len(content) {
		return string(content[start:end])
	}
	return "unknown"
}

