// convertGoJSONErrorWithContent converts Go JSON error messages to serde_json-compatible messages
func convertGoJSONErrorWithContent(goErr string, content []byte, line, col int) string {
	// Handle syntax errors
	if strings.Contains(goErr, "looking for beginning of object key string") {
		// "invalid character 'X' looking for beginning of object key string"
		return fmt.Sprintf("key must be a string at line %d column %d", line, col)
	}

	if strings.Contains(goErr, "looking for beginning of value") {
		// "invalid character 'X' looking for beginning of value"
		return fmt.Sprintf("expected value at line %d column %d", line, col)
	}

	if strings.Contains(goErr, "unexpected end of JSON input") {
		return fmt.Sprintf("EOF while parsing a value at line %d column %d", line, col)
	}

	// Handle type unmarshal errors
	if strings.Contains(goErr, "cannot unmarshal") {
		return convertUnmarshalError(goErr, content, line, col)
	}

	// Unknown field errors are handled by our validator, not by Go's json decoder
	// so this shouldn't be reached for those

	// Default: return as-is with location
	if !strings.Contains(goErr, " at line ") {
		return fmt.Sprintf("%s at line %d column %d", goErr, line, col)
	}
	return goErr
}

func convertUnmarshalError(goErr string, content []byte, line, col int) string {
	// "cannot unmarshal NUMBER into Go struct field ... of type string"
	// → "invalid type: integer `VALUE`, expected a string"

	// "cannot unmarshal string into Go struct field ... of type bool"
	// → "invalid type: string `VALUE`, expected a bool"

	// Find the actual value at the location
	actualValue := extractValueAtLocation(content, line, col)

	// Determine the Go type being unmarshaled
	if strings.Contains(goErr, "cannot unmarshal number") {
		// It's a number
		typeStr := "integer"
		if strings.Contains(actualValue, ".") {
			typeStr = "float"
		}
		// Determine expected type
		expectedType := extractExpectedType(goErr)
		return fmt.Sprintf("invalid type: %s `%s`, expected %s at line %d column %d",
			typeStr, actualValue, expectedType, line, col)
	}

	if strings.Contains(goErr, "cannot unmarshal string") {
		expectedType := extractExpectedType(goErr)
		// Strip quotes from actualValue if present
		value := actualValue
		if len(value) >= 2 && value[0] == '"' && value[len(value)-1] == '"' {
			value = value[1:len(value)-1]
		}
		return fmt.Sprintf("invalid type: string `%s`, expected %s at line %d column %d",
			value, expectedType, line, col)
	}

	if strings.Contains(goErr, "cannot unmarshal bool") {
		expectedType := extractExpectedType(goErr)
		return fmt.Sprintf("invalid type: boolean `%s`, expected %s at line %d column %d",
			actualValue, expectedType, line, col)
	}

	if strings.Contains(goErr, "cannot unmarshal array") {
		expectedType := extractExpectedType(goErr)
		return fmt.Sprintf("invalid type: sequence, expected %s at line %d column %d",
			expectedType, line, col)
	}

	if strings.Contains(goErr, "cannot unmarshal object") {
		expectedType := extractExpectedType(goErr)
		return fmt.Sprintf("invalid type: map, expected %s at line %d column %d",
			expectedType, line, col)
	}

	// Default
	return fmt.Sprintf("%s at line %d column %d", goErr, line, col)
}

func extractExpectedType(goErr string) string {
	// Extract from "... of type TYPE"
	if idx := strings.Index(goErr, "of type "); idx >= 0 {
		t := goErr[idx+8:]
		// Handle pointer types and struct types
		if strings.Contains(t, "string") {
			return "a string"
		}
		if strings.Contains(t, "bool") {
			return "a boolean"
		}
		if strings.Contains(t, "int") || strings.Contains(t, "float") {
