	}

	// Close idx = position of closing quote
	closeIdx := idx + len(needle) - 1

	// Calculate line and col for the closing quote
	line = 1
	col = 1
	for i := 0; i < closeIdx; i++ {
		if content[i] == '\n' {
			line++
			col = 1
		} else {
			col++
		}
