	// Invalid value - it must be bool or struct
	// Find the location
	offset, line, col := findValueRawLocation(content, raw)
	_ = line
	_ = col
	cause := fmt.Sprintf("data did not match any variant of untagged enum BoolOr at line %d column %d", line, col)
