// ConfigValidationError holds validation error details
type ConfigValidationError struct {
	Message string
	Cause   string
	Offset  int
	Length  int
}

func (e *ConfigValidationError) Error() string {
	return fmt.Sprintf("%s: %s", e.Message, e.Cause)
}

// lineColToByteOffset converts line/col to byte offset in content
func lineColToByteOffset(content []byte, line, col int) int {
	currentLine := 1
	lineStart := 0
	for i, b := range content {
		if currentLine == line {
			offset := lineStart + col - 1
			if offset < len(content) {
				return offset
			}
			return len(content) - 1
		}
		if b == '\n' {
			currentLine++
			lineStart = i + 1
		}
	}
	return len(content) - 1
}

// validateConfig validates the config JSON and returns a proper error
func validateConfigJSON(content []byte, filename string) (*OrandaConfig, *ConfigValidationError) {
	trimmed := strings.TrimSpace(string(content))

	var rawConfig map[string]json.RawMessage

	// First try parsing as object (standard case)
	if len(trimmed) == 0 || trimmed[0] != '[' {
		if err := json.Unmarshal(content, &rawConfig); err != nil {
			return nil, buildParseError(content, filename, err)
		}
	} else {
		// Array case
		var arr []json.RawMessage
		if err := json.Unmarshal(content, &arr); err != nil {
			return nil, buildParseError(content, filename, err)
		}
		if len(arr) > 0 {
			if err := json.Unmarshal(arr[0], &rawConfig); err != nil {
				return nil, buildParseError(content, filename, err)
			}
		}
	}

	// Validate top-level fields
	if err := validateFields(content, filename, rawConfig, topLevelFields); err != nil {
		return nil, err
	}

	// Build the config
	config := &OrandaConfig{}

	// Parse project
	if projectRaw, ok := rawConfig["project"]; ok {
		var projectMap map[string]json.RawMessage
		if err := json.Unmarshal(projectRaw, &projectMap); err != nil {
			return nil, buildParseError(content, filename, err)
		}
		if err := validateFields(content, filename, projectMap, projectFields); err != nil {
			return nil, err
		}
		// Check types
		if nameRaw, ok := projectMap["name"]; ok {
			var name string
			if err := json.Unmarshal(nameRaw, &name); err != nil {
				return nil, buildParseError(content, filename, err)
			}
		}
		project := &ProjectConfig{}
		if err := json.Unmarshal(projectRaw, project); err != nil {
			return nil, buildParseError(content, filename, err)
		}
		config.Project = project
	}

	// Parse build
	if buildRaw, ok := rawConfig["build"]; ok {
		var buildMap map[string]json.RawMessage
		if err := json.Unmarshal(buildRaw, &buildMap); err != nil {
			return nil, buildParseError(content, filename, err)
		}
		if err := validateFields(content, filename, buildMap, buildFields); err != nil {
			return nil, err
		}
		build := &BuildConfig{}
		if err := json.Unmarshal(buildRaw, build); err != nil {
			return nil, buildParseError(content, filename, err)
		}
		config.Build = build
	}

	// Parse styles
	if stylesRaw, ok := rawConfig["styles"]; ok {
		var stylesMap map[string]json.RawMessage
		if err := json.Unmarshal(stylesRaw, &stylesMap); err != nil {
			return nil, buildParseError(content, filename, err)
		}
		if err := validateFields(content, filename, stylesMap, stylesFields); err != nil {
			return nil, err
		}
		if themeRaw, ok := stylesMap["theme"]; ok {
			var theme string
			if err := json.Unmarshal(themeRaw, &theme); err != nil {
				return nil, buildParseError(content, filename, err)
			}
			if !contains(themeVariants, theme) {
				return nil, unknownVariantError(content, filename, "theme", theme, themeVariants)
			}
		}
		if stRaw, ok := stylesMap["syntax_theme"]; ok {
			var st string
			if err := json.Unmarshal(stRaw, &st); err != nil {
				return nil, buildParseError(content, filename, err)
			}
			if !contains(syntaxThemeVariants, st) {
				return nil, unknownVariantError(content, filename, "syntax_theme", st, syntaxThemeVariants)
			}
		}
		styles := &StylesConfig{}
		if err := json.Unmarshal(stylesRaw, styles); err != nil {
			return nil, buildParseError(content, filename, err)
		}
		config.Styles = styles
	}

	// Parse marketing
	if marketingRaw, ok := rawConfig["marketing"]; ok {
		var marketingMap map[string]json.RawMessage
		if err := json.Unmarshal(marketingRaw, &marketingMap); err != nil {
			return nil, buildParseError(content, filename, err)
		}
		if err := validateFields(content, filename, marketingMap, marketingFields); err != nil {
			return nil, err
		}
		if analyticsRaw, ok := marketingMap["analytics"]; ok {
			var analyticsMap map[string]json.RawMessage
			if err := json.Unmarshal(analyticsRaw, &analyticsMap); err != nil {
				return nil, buildParseError(content, filename, err)
			}
			if err := validateAnalyticsVariants(content, filename, analyticsMap); err != nil {
				return nil, err
			}
		}
		if socialRaw, ok := marketingMap["social"]; ok {
			var socialMap map[string]json.RawMessage
			if err := json.Unmarshal(socialRaw, &socialMap); err != nil {
				return nil, buildParseError(content, filename, err)
			}
			if err := validateFields(content, filename, socialMap, socialFields); err != nil {
				return nil, err
			}
		}
		marketing := &MarketingConfig{}
		if err := json.Unmarshal(marketingRaw, marketing); err != nil {
			return nil, buildParseError(content, filename, err)
		}
		config.Marketing = marketing
