func validateBoolOr(content []byte, filename, field string, raw json.RawMessage) *ConfigValidationError {
	trimmed := strings.TrimSpace(string(raw))
	if trimmed == "true" || trimmed == "false" || trimmed == "null" {
		return nil
	}
	if len(trimmed) > 0 && (trimmed[0] == '{' || trimmed[0] == '[') {
		return nil
	}
	// Invalid value - it must be bool or struct
	// Find the location
	offset, line, col := findValueRawLocation(content, raw)
	_ = line
	_ = col
	cause := fmt.Sprintf("data did not match any variant of untagged enum BoolOr at line %d column %d", line, col)
	return &ConfigValidationError{
		Message: "failed to parse JSON",
		Cause:   cause,
		Offset:  offset,
		Length:  1,
	}
}

func findValueRawLocation(content []byte, raw json.RawMessage) (offset, line, col int) {
	// Find the closing brace/bracket of this raw value in content
	rawStr := strings.TrimSpace(string(raw))
	contentStr := string(content)

	// Find the raw value in content
	idx := strings.Index(contentStr, rawStr)
	if idx < 0 {
		return 0, 1, 1
	}

	// Point to the end of the raw value
	endIdx := idx + len(rawStr) - 1

	line = 1
	col = 1
	for i := 0; i < endIdx; i++ {
		if content[i] == '\n' {
			line++
			col = 1
		} else {
			col++
		}
	}
	col++

	return endIdx, line, col
}

func validateAnalyticsVariants(content []byte, filename string, m map[string]json.RawMessage) *ConfigValidationError {
	for field := range m {
		if !contains(analyticsVariants, field) {
			return unknownVariantError(content, filename, "analytics", field, analyticsVariants)
		}
	}
	// Validate required fields
	if gRaw, ok := m["google"]; ok {
		var gMap map[string]json.RawMessage
		if err := json.Unmarshal(gRaw, &gMap); err == nil {
			if _, ok := gMap["tracking_id"]; !ok {
				return missingFieldError(content, filename, "tracking_id", gRaw)
			}
		}
	}
	if pRaw, ok := m["plausible"]; ok {
		var pMap map[string]json.RawMessage
		if err := json.Unmarshal(pRaw, &pMap); err == nil {
			if _, ok := pMap["domain"]; !ok {
				return missingFieldError(content, filename, "domain", pRaw)
			}
		}
	}
	if fRaw, ok := m["fathom"]; ok {
		var fMap map[string]json.RawMessage
		if err := json.Unmarshal(fRaw, &fMap); err == nil {
			if _, ok := fMap["site"]; !ok {
				return missingFieldError(content, filename, "site", fRaw)
			}
		}
	}
	if uRaw, ok := m["umami"]; ok {
		var uMap map[string]json.RawMessage
		if err := json.Unmarshal(uRaw, &uMap); err == nil {
			if _, ok := uMap["website"]; !ok {
				return missingFieldError(content, filename, "website", uRaw)
			}
			if _, ok := uMap["script_url"]; !ok {
				return missingFieldError(content, filename, "script_url", uRaw)
			}
		}
	}
	return nil
}

func validateFields(content []byte, filename string, m map[string]json.RawMessage, allowed []string) *ConfigValidationError {
	for field := range m {
		if !contains(allowed, field) {
			return unknownFieldError(content, filename, field, allowed)
		}
	}
	return nil
}

func contains(slice []string, s string) bool {
	for _, v := range slice {
		if v == s {
			return true
		}
	}
	return false
}

func formatExpectedListCause(fields []string) string {
	if len(fields) == 1 {
		return "`" + fields[0] + "`"
	}
	if len(fields) == 2 {
		return "`" + fields[0] + "` or `" + fields[1] + "`"
	}
	quoted := make([]string, len(fields))
	for i, f := range fields {
		quoted[i] = "`" + f + "`"
	}
	return "one of " + strings.Join(quoted, ", ")
}

func unknownFieldError(content []byte, filename string, field string, allowed []string) *ConfigValidationError {
	offset, line, col := findFieldLocation(content, field)
	expected := formatExpectedListCause(allowed)
	cause := fmt.Sprintf("unknown field `%s`, expected %s at line %d column %d",
		field, expected, line, col)
	return &ConfigValidationError{
		Message: "failed to parse JSON",
		Cause:   cause,
		Offset:  offset,
		Length:  1,
	}
}

func unknownVariantError(content []byte, filename string, context string, value string, allowed []string) *ConfigValidationError {
	expected := formatExpectedListCause(allowed)
	offset, line, col := findValueLocation(content, context, value)
	cause := fmt.Sprintf("unknown variant `%s`, expected %s at line %d column %d",
		value, expected, line, col)
	return &ConfigValidationError{
		Message: "failed to parse JSON",
		Cause:   cause,
		Offset:  offset,
		Length:  1,
	}
}

func missingFieldError(content []byte, filename string, field string, parentRaw json.RawMessage) *ConfigValidationError {
	// Find closing brace of parent
	str := string(content)
	parentStr := string(parentRaw)
	idx := strings.Index(str, parentStr)

	offset := 0
	line := 1
	col := 1

	if idx >= 0 {
		closingIdx := idx + len(parentStr) - 1
		for closingIdx >= idx && content[closingIdx] != '}' {
			closingIdx--
		}
		offset = closingIdx
		for i := 0; i < closingIdx; i++ {
			if content[i] == '\n' {
				line++
				col = 1
			} else {
				col++
			}
		}
		col++
	}

	cause := fmt.Sprintf("missing field `%s` at line %d column %d", field, line, col)
	return &ConfigValidationError{
		Message: "failed to parse JSON",
		Cause:   cause,
		Offset:  offset,
		Length:  1,
	}
}

func findFieldLocation(content []byte, fieldName string) (offset, line, col int) {
	needle := `"` + fieldName + `"`
	str := string(content)
	idx := strings.Index(str, needle)
	if idx < 0 {
		return 0, 1, 1
	}

	// Close idx = position of closing quote
	closeIdx := idx + len(needle) - 1

	// Calculate line and col for the closing quote
	line = 1
	col = 1
	for i := 0; i < closeIdx; i++ {
		if content[i] == '\n' {
			line++
			col = 1
		} else {
			col++
		}
	}
	// col is now the 1-indexed position of character before closeIdx
	// We need to add 1 to get the 1-indexed position OF closeIdx
	col++

	return closeIdx, line, col
}

func findValueLocation(content []byte, fieldName, value string) (offset, line, col int) {
	needle := `"` + fieldName + `"`
	str := string(content)
	idx := strings.Index(str, needle)
	if idx < 0 {
		return 0, 1, 1
	}

	afterField := str[idx+len(needle):]
	valueNeedle := `"` + value + `"`
	valIdx := strings.Index(afterField, valueNeedle)
	if valIdx < 0 {
		return 0, 1, 1
	}

	absoluteIdx := idx + len(needle) + valIdx + len(valueNeedle) - 1

	line = 1
	col = 1
	for i := 0; i < absoluteIdx; i++ {
		if content[i] == '\n' {
			line++
			col = 1
		} else {
			col++
		}
	}
	col++

	return absoluteIdx, line, col
}

func buildParseError(content []byte, filename string, err error) *ConfigValidationError {
	if err == nil {
		return nil
	}

	var offset int
	var msg string

	if jerr, ok := err.(*json.SyntaxError); ok {
		msg, offset = formatFromSyntaxErr(jerr, content)
	} else if jerr, ok := err.(*json.UnmarshalTypeError); ok {
		msg, offset = formatFromUnmarshalErr(jerr, content)
	} else {
		// Generic error
		msg = fmt.Sprintf("%s", err.Error())
		offset = 0
	}

	return &ConfigValidationError{
		Message: "failed to parse JSON",
		Cause:   msg,
		Offset:  offset,
		Length:  1,
	}
}
