# I need to manually check the type of each raw field value.

# For the "name" field which expects a string:
# Check if the raw value starts with '"' (it's a string)
# Otherwise, detect the type and generate the error

# Let me update the validateConfigJSON to do manual type checking

cat > /workspace/src/type_check.go << 'GOEOF'
package main

import (
	"encoding/json"
	"fmt"
	"strings"
)

// checkStringField validates that a raw JSON value is a string
// Returns a ConfigValidationError if it's not
func checkStringField(content []byte, fieldName string, raw json.RawMessage) *ConfigValidationError {
	trimmed := strings.TrimSpace(string(raw))
	if len(trimmed) == 0 {
		return nil
	}

	if trimmed[0] == '"' {
		return nil // It's a string
	}

	// Not a string - determine what it actually is
	typeStr, valueStr := getTypeAndValue(trimmed)

	offset, line, col := findFieldValueLocation(content, fieldName, trimmed)

	cause := fmt.Sprintf("invalid type: %s `%s`, expected a string at line %d column %d",
		typeStr, valueStr, line, col)

	return &ConfigValidationError{
		Message: "failed to parse JSON",
		Cause:   cause,
		Offset:  offset,
		Length:  1,
	}
}

// checkBoolField validates that a raw JSON value is a boolean
func checkBoolField(content []byte, fieldName string, raw json.RawMessage) *ConfigValidationError {
	trimmed := strings.TrimSpace(string(raw))
	if trimmed == "true" || trimmed == "false" {
		return nil
	}

	typeStr, valueStr := getTypeAndValue(trimmed)
	offset, line, col := findFieldValueLocation(content, fieldName, trimmed)

	cause := fmt.Sprintf("invalid type: %s `%s`, expected a boolean at line %d column %d",
		typeStr, valueStr, line, col)

	return &ConfigValidationError{
		Message: "failed to parse JSON",
		Cause:   cause,
		Offset:  offset,
		Length:  1,
	}
}

func getTypeAndValue(trimmed string) (typeStr, valueStr string) {
	if len(trimmed) == 0 {
		return "null", "null"
	}

	switch trimmed[0] {
	case '"':
		// String - extract content
		var s string
		if err := json.Unmarshal([]byte(trimmed), &s); err == nil {
			return "string", s
		}
		return "string", trimmed[1:len(trimmed)-1]
	case '[':
		return "sequence", "array"
	case '{':
		return "map", "object"
	case 't', 'f':
		if trimmed == "true" {
			return "boolean", "true"
		}
		return "boolean", "false"
	case 'n':
		return "null", "null"
	default:
		// Number
		typeStr = "integer"
		valueStr = trimmed
		// Check if it's a float
		if strings.Contains(trimmed, ".") || strings.ContainsAny(trimmed, "eE") {
			typeStr = "float"
		}
		// Strip any trailing non-number chars
		end := 0
		for end < len(trimmed) {
			c := trimmed[end]
			if c >= '0' && c <= '9' || c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E' {
				end++
			} else {
				break
			}
		}
		return typeStr, trimmed[:end]
	}
}

// findFieldValueLocation finds the byte offset of a field's VALUE in the content
// Returns offset, line, col of the LAST CHAR of the value
func findFieldValueLocation(content []byte, fieldName string, rawValue string) (offset, line, col int) {
	// Find the field name in content
	needle := `"` + fieldName + `"`
	str := string(content)
	fieldIdx := strings.Index(str, needle)
	if fieldIdx < 0 {
		return 0, 1, 1
	}

	// Find the value after the field name
	afterField := str[fieldIdx+len(needle):]

	// Find rawValue in the portion after the field
	valIdx := strings.Index(afterField, rawValue)
	if valIdx < 0 {
		return 0, 1, 1
	}

	// Point to the LAST character of the value
	absoluteEnd := fieldIdx + len(needle) + valIdx + len(rawValue) - 1

	line = 1
	col = 1
	for i := 0; i < absoluteEnd; i++ {
		if content[i] == '\n' {
			line++
			col = 1
		} else {
			col++
		}
	}
	col++ // 1-indexed position of the last char

	return absoluteEnd, line, col
}

GOEOF
