package main

import (
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
	"unicode/utf8"
)

const MAX_LINE_WIDTH = 119 // Lines must be < 119 chars (max 118)

// wrapCauseText wraps the cause text to fit within MAX_LINE_WIDTH
// Returns lines (first line content without prefix, continuation lines without prefix)
func wrapCauseText(cause string) []string {
	maxWidth := MAX_LINE_WIDTH
	prefixWidth := 6 // '  ╰─▶ ' = 6 display chars

	words := strings.Fields(cause)

	var lines []string
	currentLine := ""
	currentWidth := prefixWidth

	for _, word := range words {
		wWidth := utf8.RuneCountInString(word)

		if currentLine == "" {
			currentLine = word
			currentWidth += wWidth
		} else {
			newWidth := currentWidth + 1 + wWidth
			if newWidth >= maxWidth {
				lines = append(lines, currentLine)
				currentLine = word
				currentWidth = prefixWidth + wWidth
			} else {
				currentLine += " " + word
				currentWidth = newWidth
			}
		}
	}
	if currentLine != "" {
		lines = append(lines, currentLine)
	}

	return lines
}

// printDiagnosticError prints a diagnostic error in miette format
func printDiagnosticError(w io.Writer, outputFormat, filename, message, cause string, offset, length int) {
	// JSON output to stdout FIRST if json format
	if outputFormat == "json" {
		printDiagnosticJSON(filename, message, cause, offset, length)
	}

	// Human readable to stderr
	fmt.Fprintf(w, "  × %s\n", message)

	// Wrap cause text
	causeLines := wrapCauseText(cause)
	for i, cl := range causeLines {
		if i == 0 {
			fmt.Fprintf(w, "  ╰─▶ %s\n", cl)
		} else {
			fmt.Fprintf(w, "      %s\n", cl)
		}
	}

	// Show source snippet if we have file content and offset
	content, err := os.ReadFile(filename)
	if err == nil && offset >= 0 && len(content) > 0 {
