			sb.WriteString(`\\`)
		case '\n':
			sb.WriteString(`\n`)
		case '\r':
			sb.WriteString(`\r`)
		case '\t':
			sb.WriteString(`\t`)
		default:
			if r < 0x20 {
				sb.WriteString(fmt.Sprintf(`\u%04x`, r))
			} else {
				sb.WriteRune(r)
			}
		}
	}
	sb.WriteByte('"')
	return sb.String()
}

func printSourceSnippetProper(w io.Writer, filename string, content []byte, offset int, cause string) {
	// Get line/col from cause text (more reliable than from offset)
	errorLine := 1
	errorCol := 1

	if lc := parseLineColFromCause(cause); lc != nil {
		errorLine = lc[0]
		errorCol = lc[1]
	} else {
		// Calculate from offset
		for i := 0; i < offset && i < len(content); i++ {
			if content[i] == '\n' {
				errorLine++
				errorCol = 1
			} else {
				errorCol++
			}
		}
		errorCol++ // 1-indexed position
	}

	lines := strings.Split(string(content), "\n")

	// Determine range to show
	startLine := errorLine - 1
	if startLine < 1 {
		startLine = 1
	}
	endLine := errorLine + 1
	if endLine > len(lines) {
		endLine = len(lines)
	}
	// Trim empty last line
	for endLine > startLine && (endLine > len(lines) || lines[endLine-1] == "") {
		endLine--
	}
	if endLine < errorLine {
		endLine = errorLine
	}

	lineNumWidth := len(strconv.Itoa(endLine))
	if lineNumWidth < 1 {
		lineNumWidth = 1
	}

	prefixSpaces := strings.Repeat(" ", lineNumWidth+2)

	fmt.Fprintf(w, "%s╭─[%s:%d:1]\n", prefixSpaces, filename, startLine)

	for i := startLine; i <= endLine; i++ {
		lineContent := ""
		if i >= 1 && i <= len(lines) {
			lineContent = lines[i-1]
		}
		lineNum := fmt.Sprintf("%*d", lineNumWidth, i)
		fmt.Fprintf(w, " %s │ %s\n", lineNum, lineContent)

		// Show pointer on error line
		if i == errorLine {
			// pointer = prefixSpaces + '·' + errorCol*spaces + '─'
			pointerSpaces := strings.Repeat(" ", errorCol)
			fmt.Fprintf(w, "%s·%s─\n", prefixSpaces, pointerSpaces)
		}
	}

	fmt.Fprintf(w, "%s╰────\n", prefixSpaces)
}

func parseLineColFromCause(cause string) *[2]int {
	lineIdx := strings.Index(cause, "at line ")
	if lineIdx < 0 {
		return nil
	}
	rest := cause[lineIdx+8:]
	colIdx := strings.Index(rest, " column ")
	if colIdx < 0 {
		return nil
	}
	lineStr := rest[:colIdx]
	rest2 := rest[colIdx+8:]

	colStr := ""
	for _, c := range rest2 {
		if c >= '0' && c <= '9' {
			colStr += string(c)
		} else {
			break
		}
	}

	line, err1 := strconv.Atoi(strings.TrimSpace(lineStr))
	col, err2 := strconv.Atoi(colStr)
	if err1 != nil || err2 != nil {
		return nil
	}

	result := [2]int{line, col}
	return &result
}

// printSimpleError prints a simple error without source location
func printSimpleError(outputFormat, message string, causes []string) {
	fmt.Fprintf(os.Stderr, "  × %s\n", message)
	for i, c := range causes {
		if i < len(causes)-1 {
			fmt.Fprintf(os.Stderr, "  ├─▶ %s\n", c)
		} else {
			fmt.Fprintf(os.Stderr, "  ╰─▶ %s\n", c)
		}
	}
	if len(causes) > 0 {
		fmt.Fprintf(os.Stderr, "\n")
	}

	if outputFormat == "json" {
		var sb strings.Builder
		sb.WriteString(`{"diagnostic": {`)
		sb.WriteString(fmt.Sprintf(`"message": %s`, jsonString(message)))
		sb.WriteString(`,"severity": "error","causes": [`)
		for i, c := range causes {
			if i > 0 {
				sb.WriteString(`,`)
			}
			sb.WriteString(jsonString(c))
		}
		sb.WriteString(`],"filename": null,"labels": [],"related": []}}`)
		fmt.Println(sb.String())
	}
}
